with valid as (select id, order_id, shipped_date, delivered_date, status, initcap(trim(status)) status_title, round(cost, 2) cost_rounded from shipments where carrier is not null and month(shipped_date) in (3, 8, 12)) select id, order_id, shipped_date, cume_dist() over (order by cost_rounded desc nulls first) cost_rounded_cume_dist, lag(cost_rounded, 1) over (partition by order_id order by delivered_date, id) prev_cost_rounded, ntile(3) over (partition by month(delivered_date), status order by cost_rounded, id) cost_rounded_bucket from valid where order_id = 27;
